# owner: platform
"""Find uncovered stretches of opening hours."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import intersect_spans, merge_spans

# ---
def gap_labels(
    worked: Iterable[Span], opening: Span
) -> List[str]:
    """One label per uncovered stretch of opening hours."""
    worked = list(worked)
    _check_inside(worked, opening)
    stretches = _gaps(merge_spans(worked), opening)
    return [_label(stretch) for stretch in stretches]

def _check_inside(spans: List[Span], opening: Span) -> None:
    for span in spans:
        if intersect_spans(span, opening) != span:
            raise ValueError(
                f"outside opening: {format_span(span)}"
            )

def _gaps(spans: List[Span], opening: Span) -> List[Span]:
    starts = [opening.start] + [span.end for span in spans]
    ends = [span.start for span in spans] + [opening.end]
    found = []
    for first, last in zip(starts, ends):
        if first < last:
            found.append(Span(first, last))
    return found

def _label(stretch: Span) -> str:
    span_text = format_span(stretch)
    return f"gap {span_text} ({stretch.minutes} min)"
